(37, NULL, 2, 5, 'Pengembangan dan Monitoring Kegiatan Hilirisasi', 'Mendukung pengelolaan kegiatan hilirisasi, dokumentasi proses, evaluasi hasil, serta penyusunan laporan perkembangan.', 43, 0.00, '2026-09-01', '2026-09-30', 'active', '2026-10-21 02:33:28', '2026-10-21 03:21:54'),
