(387, 52, NULL, 'independent', '2026-09-23 16:42:00', 'Turmeric primer selection and DNA extraction sample preparation\r\n\r\n1. Completed turmeric primer selection and finalized the selected primer candidates.\r\n2.  Selected available turmeric (Curcuma longa) samples for DNA extraction scheduled for tomorrow', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/open?id=1as1wZ5HvP6HpHtkeowC6kMJGOSAIaRt_', '[\"https:\\/\\/drive.google.com\\/open?id=1as1wZ5HvP6HpHtkeowC6kMJGOSAIaRt_\",\"https:\\/\\/drive.google.com\\/open?id=1fr2VwYEpGBlRfYbyicTWTenHlL1gldSg\"]', NULL, 'approved', NULL, 46, '2026-11-09 09:55:59', NULL, '2026-11-09 09:43:11', '2026-11-09 09:55:59'),
(388, 52, NULL, 'independent', '2026-09-24 16:49:00', 'DNA extraction of six Curcuma accessions, quality control, and turmeric database update\r\n\r\n1.Extracted DNA from six turmeric (Curcuma longa) accessions: CEK-1, CEK-2, CEK-50, CL-45, CL-64, and CL-90.\r\n2. Measured DNA quality and concentration using NanoDrop and Qubit Fluorometer.\r\n3. Updated the turmeric field survey data in the Excel dataset to support sample selection for future DNA extraction.\r\n4. Updated the turmeric accession database, including records of samples that have undergone DNA extraction and electrophoresis.', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/open?id=1vUxabcqwVye0cPZqWek5pQj8w0wc-7ho', '[\"https:\\/\\/drive.google.com\\/open?id=1vUxabcqwVye0cPZqWek5pQj8w0wc-7ho\",\"https:\\/\\/drive.google.com\\/open?id=1EnxzDiF-okoC7Bxpp1-RpVr878VUPBjg\"]', NULL, 'approved', NULL, 46, '2026-11-09 09:56:24', NULL, '2026-11-09 09:44:23', '2026-11-09 09:56:24'),
(389, 52, NULL, 'independent', '2026-09-25 13:44:00', 'DNA extraction of four Curcuma accessions \r\n\r\n1.Extracted DNA from six turmeric (Curcuma longa) accessions: CEK-3, , CL-05, CL-79, and CL-92.\r\n2. Measured DNA quality and concentration using NanoDrop\r\n3. Prepared and stood by as backup MC for the DEN Chair\'s and guest visit to TSTH2.', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/open?id=1pndIR-dz2TxX4MgIaxnq3Gg-EQGUGDuM', '[\"https:\\/\\/drive.google.com\\/open?id=1pndIR-dz2TxX4MgIaxnq3Gg-EQGUGDuM\",\"https:\\/\\/drive.google.com\\/open?id=1TwTIFvwnY0MIBBJAev0IvhT2nvEdHcOe\"]', NULL, 'approved', NULL, 46, '2026-11-09 09:56:33', NULL, '2026-11-09 09:45:51', '2026-11-09 09:56:33'),
